import { cssExpressionForToken } from '../resolver';
import { cssVarName, type DesignSystemDocument } from '../types';

/** Emit project CSS custom properties for light (:root) and dark themes. */
export function emitDesignTokensCss(doc: DesignSystemDocument): string {
  const lines: string[] = [
    '/* Generated by OpenCanvas — do not edit by hand. Source: .opencanvas/design-system.json */',
    '',
  ];

  const lightTheme = doc.themes.find((t) => !t.isDark)?.id ?? doc.activeThemeId;
  const darkTheme = doc.themes.find((t) => t.isDark)?.id;

  const emitBlock = (selector: string, themeId: string) => {
    lines.push(`${selector} {`);
    for (const token of doc.tokens) {
      try {
        const expr = cssExpressionForToken(doc, token, themeId);
        lines.push(`  ${cssVarName(token.path)}: ${expr};`);
      } catch {
        /* skip broken tokens; validator surfaces them */
      }
    }
    lines.push('}', '');
  };

  emitBlock(':root', lightTheme);
  if (darkTheme) {
    emitBlock('[data-theme="dark"]', darkTheme);
    emitBlock('.dark', darkTheme);
  }

  return lines.join('\n');
}
